 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    # Find filled rectangular frames, whose outlines are complete solid edges.
    frames = []
    for r0 in range(h):
        for c0 in range(w):
            color = grid[r0][c0]
            if color == 0 or (r0 and grid[r0-1][c0] == color) or (c0 and grid[r0][c0-1] == color):
                continue
            for r1 in range(r0 + 2, h):
                for c1 in range(c0 + 2, w):
                    if all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0, c1+1)) and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1+1)):
                        frames.append((r0,c0,r1,c1,color))
                        break
                if frames and frames[-1][0] == r0 and frames[-1][1] == c0:
