    # Keep only maximal unique frames.
    frames = list(dict.fromkeys(frames))
    for r0,c0,r1,c1,color in frames:
        for c in range(c0,c1+1):
            out[r0][c] = out[r1][c] = color
        for r in range(r0,r1+1):
            out[r][c0] = out[r][c1] = color
    frame_cells = {(r,c) for r in range(h) for c in range(w) if out[r][c]}
    counts = {}
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v and (r,c) not in frame_cells:
                counts[v]=counts.get(v,0)+1
    for r0,c0,r1,c1,color in frames:
        ih, iw = r1-r0-1, c1-c0-1
        need = (ih*iw)//2
        candidates = [v for v,n in counts.items() if n == need]
        if candidates:
            fill = candidates[0]
            # Checkerboard, with the phase selected by which parity has the required count.
            parity0 = sum(1 for r in range(ih) for c in range(iw) if (r+c)%2==0)
            parity1 = ih*iw-parity0
            phase = 0 if parity0 == need else 1
            for r in range(ih):
                for c in range(iw):
                    if (r+c)%2 == phase:
                        out[r0+1+r][c0+1+c] = fill
    return out

